// ---------- Isomer counting (exhaustive search over the octahedron's symmetry; used to key and verify the isomer items) ----------
const ROTG = (() => {
  const rz = [2, 3, 1, 0, 4, 5], rx = [0, 1, 4, 5, 3, 2], inv = [1, 0, 3, 2, 5, 4];
  const comp = (a, b) => a.map((_, i) => a[b[i]]);
  const close = (gens) => { const seen = new Map([[gens[0].join(), gens[0]]]); const id = [0, 1, 2, 3, 4, 5]; seen.set(id.join(), id); let ch = true; while (ch) { ch = false; for (const a of [...seen.values()]) for (const g of gens) { const c = comp(g, a); if (!seen.has(c.join())) { seen.set(c.join(), c); ch = true; } } } return [...seen.values()]; };
  const rot = close([rz, rx]); const full = close([rz, rx, inv]);
  return { rot, full };
})();
/** units: array of strings. A single letter is a monodentate ligand; a two-letter string such as 'AA' or 'AB' is a bidentate
 *  ligand (donor atoms A and B) spanning two cis positions. Returns { total, geo }: stereoisomers (counting each enantiomer) and geometrical isomers. */
function isoOct(units) {
  const arrs = new Set(); const pos = new Array(6).fill(null);
  const go = (k) => {
    if (k === units.length) { arrs.add(pos.map((t) => t.l + (t.p === undefined ? '' : '@' + t.p)).join('|')); return; }
    const u = units[k];
    if (u.length === 1) { for (let i = 0; i < 6; i++) if (!pos[i]) { pos[i] = { l: u }; go(k + 1); pos[i] = null; } } else {
      for (let i = 0; i < 6; i++) for (let j = 0; j < 6; j++) if (i !== j && (i ^ 1) !== j && !pos[i] && !pos[j]) { pos[i] = { l: u[0], p: j }; pos[j] = { l: u[1], p: i }; go(k + 1); pos[i] = pos[j] = null; }
    }
  };
  go(0);
  const orbits = (G) => { const seen = new Set(); let n = 0; for (const a of arrs) { if (seen.has(a)) continue; n++; const toks = a.split('|').map((t) => { const [l, p] = t.split('@'); return { l, p: p === undefined ? undefined : +p }; }); for (const g of G) { const b = new Array(6); toks.forEach((t, i) => { b[g[i]] = t.l + (t.p === undefined ? '' : '@' + g[t.p]); }); seen.add(b.join('|')); } } return n; };
  return { total: orbits(ROTG.rot), geo: orbits(ROTG.full) };
}
/** Square planar MA..: monodentate letters only; returns the number of geometrical isomers. */
function isoSq(units) {
  const G = []; for (let r = 0; r < 4; r++) { G.push([0, 1, 2, 3].map((i) => (i + r) % 4)); G.push([0, 1, 2, 3].map((i) => (r - i + 4) % 4)); }
  const arrs = new Set(); const rec = (rest, cur) => { if (!rest.length) { arrs.add(cur.join('')); return; } new Set(rest).forEach((x) => { const r = [...rest]; r.splice(r.indexOf(x), 1); rec(r, [...cur, x]); }); };
  rec(units, []); const seen = new Set(); let n = 0;
  for (const a of arrs) { if (seen.has(a)) continue; n++; for (const g of G) { const b = []; a.split('').forEach((l, i) => { b[g[i]] = l; }); seen.add(b.join('')); } }
  return n;
}
